INSERT INTO problems (id, owner_teacher_id, visibility, statement, func_name, param_names, rubric, reference_solution, test_cases, starter_code, created_at, title, category, difficulty) VALUES ('bank:P11_caesar_cipher', NULL, 'system', 'Write a function caesar_encrypt(s, shift) that shifts every letter in s forward by `shift` positions in the alphabet, wrapping around from z back to a (and Z back to A). Non-letter characters are left unchanged. Preserve the original case of each letter.', 'caesar_encrypt', '["s", "shift"]', '{"correctness": 55, "efficiency": 10, "code_style": 15, "edge_case_handling": 20}', 'def caesar_encrypt(s, shift):
    result = []
    for ch in s:
        if ch.isupper():
            result.append(chr((ord(ch) - ord(''A'') + shift) % 26 + ord(''A'')))
        elif ch.islower():
            result.append(chr((ord(ch) - ord(''a'') + shift) % 26 + ord(''a'')))
        else:
            result.append(ch)
    return "".join(result)
', '[{"args": ["abc", 1], "expected": "bcd", "is_public": true}, {"args": ["xyz", 1], "expected": "yza", "is_public": false}, {"args": ["Hello, World!", 3], "expected": "Khoor, Zruog!", "is_public": false}, {"args": ["abc", 0], "expected": "abc", "is_public": false}, {"args": ["XYZ", 2], "expected": "ZAB", "is_public": false}, {"args": ["", 5], "expected": "", "is_public": false}]', 'def caesar_encrypt(s, shift):
    # TODO: your solution here
    pass
', '2026-01-01T00:00:00+00:00', 'Caesar Cipher', 'Strings', 'medium') ON CONFLICT(id) DO UPDATE SET title = excluded.title, category = excluded.category, difficulty = excluded.difficulty;
INSERT INTO problems (id, owner_teacher_id, visibility, statement, func_name, param_names, rubric, reference_solution, test_cases, starter_code, created_at, title, category, difficulty) VALUES ('bank:P12_valid_parentheses', NULL, 'system', 'Write a function valid_parentheses(s) that returns True if every opening bracket in s (''('', ''['', ''{'') has a matching closing bracket in the correct order, False otherwise. s may also contain other characters, which should be ignored.', 'valid_parentheses', '["s"]', '{"correctness": 60, "efficiency": 10, "code_style": 15, "edge_case_handling": 15}', 'def valid_parentheses(s):
    pairs = {'')'': ''('', '']'': ''['', ''}'': ''{''}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
', '[{"args": ["()"], "expected": true, "is_public": true}, {"args": ["()[]{}"], "expected": true, "is_public": false}, {"args": ["(]"], "expected": false, "is_public": false}, {"args": ["([)]"], "expected": false, "is_public": false}, {"args": ["{[]}"], "expected": true, "is_public": false}, {"args": [""], "expected": true, "is_public": false}, {"args": ["("], "expected": false, "is_public": false}, {"args": ["[[["], "expected": false, "is_public": false}]', 'def valid_parentheses(s):
    # TODO: your solution here
    pass
', '2026-01-01T00:00:00+00:00', 'Valid Parentheses', 'Data Structures', 'medium') ON CONFLICT(id) DO UPDATE SET title = excluded.title, category = excluded.category, difficulty = excluded.difficulty;
INSERT INTO problems (id, owner_teacher_id, visibility, statement, func_name, param_names, rubric, reference_solution, test_cases, starter_code, created_at, title, category, difficulty) VALUES ('bank:P13_merge_sorted_lists', NULL, 'system', 'Write a function merge_sorted_lists(a, b) that merges two sorted (ascending) lists of integers into a single sorted (ascending) list, keeping all duplicates.', 'merge_sorted_lists', '["a", "b"]', '{"correctness": 55, "efficiency": 20, "code_style": 10, "edge_case_handling": 15}', 'def merge_sorted_lists(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result
', '[{"args": [[1, 3, 5], [2, 4, 6]], "expected": [1, 2, 3, 4, 5, 6], "is_public": true}, {"args": [[], [1, 2, 3]], "expected": [1, 2, 3], "is_public": false}, {"args": [[1, 2, 3], []], "expected": [1, 2, 3], "is_public": false}, {"args": [[], []], "expected": [], "is_public": false}, {"args": [[1, 1, 2], [1, 3]], "expected": [1, 1, 1, 2, 3], "is_public": false}, {"args": [[5], [1]], "expected": [1, 5], "is_public": false}]', 'def merge_sorted_lists(a, b):
